'use client'

import { useState, useEffect, useCallback } from 'react'
import { useRouter } from 'next/navigation'
import { supabase } from '@/lib/supabase'
import Link from 'next/link'
import { useLang } from '@/lib/LanguageContext'

type Order = {
  id: string
  farmer_id: string
  produce_listing_id: string | null
  produce_name: string | null
  quantity: number | null
  unit: string | null
  total_price: number | null
  buyer_name: string | null
  buyer_phone: string | null
  pickup_location: string | null
  status: 'pending' | 'approved' | 'declined'
  created_at: string
}

type Filter = 'today' | 'week' | 'month'

export default function OrderHistoryPage() {
  const router = useRouter()
  const { tx } = useLang()
  const [orders, setOrders] = useState<Order[]>([])
  const [loading, setLoading] = useState(true)
  const [filter, setFilter] = useState<Filter>('week')

  const load = useCallback(async () => {
    const farmerId = localStorage.getItem('yff_farmer_id')
    if (!farmerId) { router.replace('/farmer/login'); return }

    setLoading(true)
    const { data } = await supabase
      .from('orders')
      .select('*')
      .eq('farmer_id', farmerId)
      .in('status', ['approved', 'declined'])
      .order('created_at', { ascending: false })

    setOrders((data ?? []) as Order[])
    setLoading(false)
  }, [router])

  useEffect(() => { load() }, [load])

  const filterStart = () => {
    if (filter === 'today') {
      const d = new Date()
      d.setHours(0, 0, 0, 0)
      return d.getTime()
    }
    if (filter === 'week') return Date.now() - 7 * 86400000
    return Date.now() - 30 * 86400000
  }

  const filtered = orders.filter((o) => new Date(o.created_at).getTime() >= filterStart())
  const revenue = filtered
    .filter((o) => o.status === 'approved')
    .reduce((sum, o) => sum + (o.total_price ?? 0), 0)

  return (
    <main className="min-h-screen bg-gray-50 pb-16">
      {/* Header */}
      <div className="bg-green-900 px-4 pt-6 pb-10">
        <Link href="/farmer/dashboard" className="text-green-300 text-sm flex items-center gap-1 mb-4">
          ← {tx.back}
        </Link>
        <h1 className="text-white text-xl font-extrabold leading-tight">
          {tx.orderHistory}
        </h1>
        <p className="text-green-400 text-sm mt-1">Approved &amp; declined orders</p>
      </div>

      <div className="px-4 -mt-5 space-y-4">
        {/* Filter pills */}
        <div className="bg-white rounded-2xl border border-gray-100 p-3 flex gap-2">
          {(['today', 'week', 'month'] as const).map((f) => (
            <button
              key={f}
              onClick={() => setFilter(f)}
              className={`flex-1 py-2.5 rounded-xl text-xs font-bold transition-colors ${
                filter === f ? 'bg-green-700 text-white' : 'bg-gray-100 text-gray-600 active:bg-gray-200'
              }`}
            >
              {f === 'today' ? tx.filterToday : f === 'week' ? tx.filterWeek : tx.filterMonth}
            </button>
          ))}
        </div>

        {/* Revenue summary */}
        {revenue > 0 && (
          <div className="bg-green-50 border border-green-200 rounded-2xl p-4 flex items-center justify-between">
            <div>
              <p className="text-xs font-semibold text-green-700 uppercase tracking-wide">
                {tx.totalRevenue}
              </p>
              <p className="text-3xl font-black text-green-800 mt-0.5">₹{revenue}</p>
            </div>
            <div className="text-4xl">💰</div>
          </div>
        )}

        {/* Order list */}
        {loading ? (
          <div className="text-center py-16">
            <div className="w-10 h-10 border-4 border-green-700 border-t-transparent rounded-full animate-spin mx-auto" />
            <p className="text-gray-500 text-sm mt-3">{tx.loadingLabel}</p>
          </div>
        ) : filtered.length === 0 ? (
          <div className="text-center py-16">
            <div className="text-5xl mb-3">📭</div>
            <p className="font-semibold text-gray-500 text-sm">{tx.noPendingOrders}</p>
          </div>
        ) : (
          <div className="space-y-3">
            {filtered.map((order) => (
              <HistoryCard key={order.id} order={order} />
            ))}
          </div>
        )}
      </div>
    </main>
  )
}

function HistoryCard({ order }: { order: Order }) {
  const isApproved = order.status === 'approved'

  const timeStr = new Date(order.created_at).toLocaleDateString('en-IN', {
    day: 'numeric',
    month: 'short',
    hour: '2-digit',
    minute: '2-digit',
  })

  return (
    <div className={`rounded-2xl border overflow-hidden ${isApproved ? 'border-green-200 bg-white' : 'border-gray-200 bg-gray-50'}`}>
      <div className="p-3 space-y-1.5">
        <div className="flex items-start justify-between gap-2">
          <div className="min-w-0">
            <div className="flex items-center gap-2 flex-wrap">
              <p className="font-extrabold text-gray-900 text-sm leading-tight">
                {order.buyer_name || '—'}
              </p>
              <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full ${
                isApproved ? 'bg-green-100 text-green-800' : 'bg-red-100 text-red-700'
              }`}>
                {isApproved ? '✓ Approved' : '✕ Declined'}
              </span>
            </div>
            {order.buyer_phone && (
              <a href={`tel:+91${order.buyer_phone}`} className="text-xs font-semibold text-green-700">
                📞 +91 {order.buyer_phone}
              </a>
            )}
          </div>
          <span className="text-[11px] text-gray-400 whitespace-nowrap flex-shrink-0 mt-0.5">
            {timeStr}
          </span>
        </div>

        <div className="flex flex-wrap items-center gap-1.5 text-sm">
          <span className="font-semibold text-gray-800">{order.produce_name || '—'}</span>
          <span className="text-gray-300">·</span>
          <span className="text-gray-600">{order.quantity} {order.unit || 'kg'}</span>
          {order.total_price != null && order.total_price > 0 && (
            <>
              <span className="text-gray-300">·</span>
              <span className="font-bold text-green-700">₹{order.total_price}</span>
            </>
          )}
        </div>

        {order.pickup_location && (
          <p className="text-xs text-gray-500">📍 {order.pickup_location}</p>
        )}
      </div>
    </div>
  )
}

import { createClient } from '@supabase/supabase-js'
import { NextRequest, NextResponse } from 'next/server'
import { getFarmerSessionFromRequest } from '@/lib/farmer-session'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i

// Disallowed payload keys — never let the client mutate ownership, status
// flags, or audit columns through this generic update endpoint.
const FORBIDDEN_KEYS = new Set([
  'id', 'farmer_id', 'created_at', 'updated_at',
])

export async function POST(request: NextRequest) {
  // farmerId now comes from the signed cookie, not the request body.
  const session = getFarmerSessionFromRequest(request)
  if (!session) return NextResponse.json({ error: 'Please log in first.' }, { status: 401 })

  const supabaseAdmin = createClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.SUPABASE_SERVICE_ROLE_KEY!,
  )

  const body = await request.json().catch(() => null)
  if (!body || typeof body !== 'object') {
    return NextResponse.json({ error: 'Invalid request' }, { status: 400 })
  }

  const { listingId, payload } = body as { listingId?: unknown; payload?: unknown }
  if (typeof listingId !== 'string' || !UUID_RE.test(listingId)) {
    return NextResponse.json({ error: 'Invalid listing id' }, { status: 400 })
  }
  if (!payload || typeof payload !== 'object' || Array.isArray(payload)) {
    return NextResponse.json({ error: 'Invalid payload' }, { status: 400 })
  }

  // Strip any forbidden keys before forwarding to the DB.
  const cleanPayload: Record<string, unknown> = {}
  for (const [k, v] of Object.entries(payload as Record<string, unknown>)) {
    if (!FORBIDDEN_KEYS.has(k)) cleanPayload[k] = v
  }

  // Verify the listing belongs to the logged-in farmer.
  const { data: existing } = await supabaseAdmin
    .from('produce_listings')
    .select('id')
    .eq('id', listingId)
    .eq('farmer_id', session.farmerId)
    .maybeSingle()

  if (!existing) {
    return NextResponse.json({ error: 'Listing not found or access denied' }, { status: 403 })
  }

  const { data: updated, error } = await supabaseAdmin
    .from('produce_listings')
    .update(cleanPayload)
    .eq('id', listingId)
    .eq('farmer_id', session.farmerId)
    .select('id')

  if (error) return NextResponse.json({ error: error.message }, { status: 500 })
  if (!updated?.length) return NextResponse.json({ error: 'Update failed' }, { status: 500 })

  return NextResponse.json({ ok: true })
}

import { createClient } from '@supabase/supabase-js'
import { NextRequest, NextResponse } from 'next/server'
import { getConsumerSessionFromRequest } from '@/lib/session'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i

export async function GET(req: NextRequest, ctx: { params: Promise<{ id: string }> }) {
  const session = getConsumerSessionFromRequest(req)
  if (!session) return NextResponse.json({ error: 'Login required.' }, { status: 401 })

  const { id } = await ctx.params
  if (!id || !UUID_RE.test(id)) return NextResponse.json({ error: 'Invalid order id.' }, { status: 400 })

  const supabase = createClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.SUPABASE_SERVICE_ROLE_KEY!,
  )

  const { data: order, error } = await supabase
    .from('orders')
    .select(
      'id, consumer_id, produce_name, quantity, unit, total_price, pickup_location, status, payment_method, payment_status, decline_reason, payment_proof_path, created_at, farmer_id, delivery_type, delivery_status, delivery_address, delivery_landmark, delivery_pincode, delivery_alt_phone, delivery_boy_id, handover_otp, assigned_at, picked_up_at, out_for_delivery_at, delivered_at',
    )
    .eq('id', id)
    .maybeSingle()

  if (error) return NextResponse.json({ error: error.message }, { status: 500 })
  if (!order) return NextResponse.json({ error: 'Order not found.' }, { status: 404 })
  if (order.consumer_id !== session.consumerId) {
    return NextResponse.json({ error: 'Not your order.' }, { status: 403 })
  }

  // Manual farmer join (no FK on orders.farmer_id → farmers.id, so embedding fails)
  let farmer: { name: string; slug: string; village: string; phone: string | null; upi_id: string | null } | null = null
  if (order.farmer_id) {
    const { data: f } = await supabase
      .from('farmers')
      .select('id, name, slug, village, phone, upi_id')
      .eq('id', order.farmer_id)
      .maybeSingle()
    if (f) {
      farmer = {
        name: f.name,
        slug: f.slug,
        village: f.village,
        phone: f.phone ?? null,
        upi_id: (f.upi_id as string | null) ?? null,
      }
    }
  }

  // Rider contact (only after a rider has been assigned). Minimal exposure:
  // name + phone, nothing else.
  let rider: { id: string; name: string | null; phone: string } | null = null
  const dbi = (order as { delivery_boy_id?: string | null }).delivery_boy_id ?? null
  if (dbi) {
    const { data: r } = await supabase
      .from('delivery_boys')
      .select('id, name, phone')
      .eq('id', dbi)
      .maybeSingle()
    if (r) rider = { id: r.id, name: r.name ?? null, phone: r.phone }
  }

  return NextResponse.json({ order: { ...order, farmer, rider } })
}

const [notFound, setNotFound] = useState(false)
const [activeListings, setActiveListings] = useState(0)
const [pendingOrders, setPendingOrders] = useState<Order[]>([])
const [approvedCount, setApprovedCount] = useState(0)
const [totalRevenue, setTotalRevenue] = useState(0)
const [ordersFilter, setOrdersFilter] = useState<'today' | 'week' | 'month'>('week')
const [processingOrderId, setProcessingOrderId] = useState<string | null>(null)
const [processingPaidId, setProcessingPaidId] = useState<string | null>(null)
const [decliningOrder, setDecliningOrder] = useState<Order | null>(null)
const [demandBars, setDemandBars] = useState<DemandBar[]>([])
const [monthlyRevenue, setMonthlyRevenue] = useState(0)
const [monthlyOrderCount, setMonthlyOrderCount] = useState(0)
const [weeklyEarnings, setWeeklyEarnings] = useState<number[]>([0, 0, 0, 0])
const [showForm, setShowForm] = useState(false)
const [showProfileEdit, setShowProfileEdit] = useState(false)
const [showListings, setShowListings] = useState(false)

const loadDashboard = useCallback(async () => {
  const farmerId = localStorage.getItem('yff_farmer_id')
  if (!farmerId) { router.replace('/farmer/login'); return }

  const { data: farmerData } = await supabase
    .from('farmers')
    .select('*')
    .eq('id', farmerId)
    .maybeSingle()

  if (!farmerData) { setNotFound(true); setLoading(false); return }
  setFarmer(farmerData)

  const monthStart = new Date()
  monthStart.setDate(1)
  monthStart.setHours(0, 0, 0, 0)

  const [listingsRes, pendingRes, approvedRes, intentsRes, monthlyRes] = await Promise.all([
    supabase.from('produce_listings').select('id', { count: 'exact', head: true }).eq('farmer_id', farmerData.id).eq('status', 'available'),
    supabase.from('orders').select('*').eq('farmer_id', farmerData.id).eq('status', 'pending').order('created_at', { ascending: false }),
    supabase.from('orders').select('id, total_price').eq('farmer_id', farmerData.id).eq('status', 'approved').gte('created_at', new Date(Date.now() - 7 * 86400000).toISOString()),
    supabase.from('demand_intents').select('crop_name, quantity_kg').eq('region_slug', farmerData.region_slug).eq('fulfilled', false),
    supabase.from('orders').select('id, total_price, created_at').eq('farmer_id', farmerData.id).eq('status', 'approved').gte('created_at', monthStart.toISOString()),
  ])

  setActiveListings(listingsRes.count ?? 0)
  setPendingOrders((pendingRes.data ?? []) as Order[])
  const approved = approvedRes.data ?? []
  setApprovedCount(approved.length)
  setTotalRevenue(approved.reduce((sum, o) => sum + (o.total_price ?? 0), 0))

  // Monthly earnings
  const monthly = monthlyRes.data ?? []
  setMonthlyRevenue(monthly.reduce((sum, o) => sum + (o.total_price ?? 0), 0))
  setMonthlyOrderCount(monthly.length)

  // Break into 4 weekly buckets (days 1-7, 8-14, 15-21, 22+)
  const weeks = [0, 0, 0, 0]
  for (const o of monthly) {
    const day = new Date(o.created_at).getDate()
    const bucket = day <= 7 ? 0 : day <= 14 ? 1 : day <= 21 ? 2 : 3
    weeks[bucket] += o.total_price ?? 0
  }
  setWeeklyEarnings(weeks)

  const map: Record<string, number> = {}
  for (const row of intentsRes.data ?? []) {
    map[row.crop_name] = (map[row.crop_name] ?? 0) + (Number(row.quantity_kg) || 0)
  }
  setDemandBars(
    Object.entries(map)
      .map(([crop_name, total_qty]) => ({ crop_name, total_qty }))
      .sort((a, b) => b.total_qty - a.total_qty)
      .slice(0, 5)
  )

  setLoading(false)
}, [router])

useEffect(() => { loadDashboard() }, [loadDashboard])

// Auto-open the profile edit modal the first time an incomplete farmer lands here.
useEffect(() => {
  if (!loading && farmer && !isProfileComplete(farmer)) {
    setShowProfileEdit(true)
  }
}, [loading, farmer])

// Realtime subscription: new orders + payment status changes.
// Replaces the old "consumer opens WhatsApp to notify farmer" flow.
// Fires a browser notification when:
//   - A new pending order is inserted
//   - An existing order's payment_status flips to payment_claimed (incl. retries)
useEffect(() => {
  if (!farmer) return

  const fireNotification = (title: string, body: string) => {
    if (typeof window === 'undefined') return
    if (!('Notification' in window)) return
    if (Notification.permission !== 'granted') return
    try {
      new Notification(title, { body, icon: '/icon-192.png', tag: 'yff-order' })
    } catch { /* some browsers throw on background tabs — ignore */ }
  }

  const channel = supabase
    .channel(`orders_${farmer.id}`)
    .on(
      'postgres_changes',
      { event: 'INSERT', schema: 'public', table: 'orders', filter: `farmer_id=eq.${farmer.id}` },
      (payload) => {
        const row = payload.new as Order
        if (row.status !== 'pending') return
        setPendingOrders((prev) => prev.some((o) => o.id === row.id) ? prev : [row, ...prev])
        fireNotification(
          `New order from ${row.buyer_name ?? 'buyer'}`,
          `${row.produce_name ?? ''} ${row.quantity ?? ''} ${row.unit ?? ''}${row.total_price ? ` · ₹${row.total_price}` : ''}`.trim(),
        )
      },
    )
    .on(
      'postgres_changes',
      { event: 'UPDATE', schema: 'public', table: 'orders', filter: `farmer_id=eq.${farmer.id}` },
      (payload) => {
        const row = payload.new as Order
        const prev = payload.old as Partial<Order>
        // Order moved out of pending — drop from list
        if (row.status !== 'pending') {
          setPendingOrders((cur) => cur.filter((o) => o.id !== row.id))
          return
        }
        // Update or insert in pending list
        setPendingOrders((cur) => {
          const exists = cur.some((o) => o.id === row.id)
          return exists ? cur.map((o) => o.id === row.id ? row : o) : [row, ...cur]
        })
        // Fire notification when buyer claims payment (covers initial pay AND retry)
        const becameClaimed =
          (row.payment_status === 'payment_claimed' || row.payment_status === 'pending_confirmation')
          && prev.payment_status !== row.payment_status
        if (becameClaimed) {
          fireNotification(
            `Buyer paid — verify payment`,
            `${row.buyer_name ?? 'Buyer'} sent ₹${row.total_price ?? '?'} for ${row.produce_name ?? 'order'}`,
          )
        }
      },
    )
    .subscribe()

  return () => { supabase.removeChannel(channel) }
}, [farmer])

const handleLogout = () => {
  localStorage.removeItem('yff_farmer_id')
  localStorage.removeItem('yff_farmer_slug')
  router.replace('/farmer/login')
}

const handleApprove = async (orderId: string) => {
  setProcessingOrderId(orderId)
  await supabase.from('orders').update({ status: 'approved' }).eq('id', orderId)
  setPendingOrders((prev) => prev.filter((o) => o.id !== orderId))
  setApprovedCount((c) => c + 1)
  setProcessingOrderId(null)
}

const handleConfirmDecline = async (orderId: string, reason: string) => {
  setProcessingOrderId(orderId)
  // Return the reserved stock so a farmer who declines doesn't lose it.
  const declined = pendingOrders.find((o) => o.id === orderId)
  if (declined?.produce_listing_id && declined.quantity != null && declined.quantity > 0) {
    try {
      await supabase.rpc('increment_stock', {
        p_listing_id: declined.produce_listing_id,
        p_qty: declined.quantity,
      })
    } catch (e) {
      console.error('[YFF] restock on decline failed:', e)
    }
  }
  await supabase
    .from('orders')
    .update({ status: 'declined', decline_reason: reason })
    .eq('id', orderId)
  setPendingOrders((prev) => prev.filter((o) => o.id !== orderId))
  setProcessingOrderId(null)
  setDecliningOrder(null)
}

const handleMarkPaid = async (orderId: string) => {
  setProcessingPaidId(orderId)
  await supabase.from('orders').update({ payment_status: 'completed' }).eq('id', orderId)
  setPendingOrders((prev) =>
    prev.map((o) => o.id === orderId ? { ...o, payment_status: 'completed' } : o)
  )
  setProcessingPaidId(null)
}

const handleUpdatePaymentStatus = async (orderId: string, status: 'completed' | 'failed' | 'pending') => {
  setProcessingPaidId(orderId)
  const update: Record<string, string> = { payment_status: status }
  if (status === 'completed') update.status = 'approved'
  await supabase.from('orders').update(update).eq('id', orderId)
  setPendingOrders((prev) =>
    prev.map((o) => o.id === orderId ? { ...o, payment_status: status, ...(status === 'completed' ? { status: 'approved' } : {}) } : o)
  )
  setProcessingPaidId(null)
}

const filteredPendingOrders = pendingOrders.filter((o) => {
  const t = new Date(o.created_at).getTime()
  const now = Date.now()
  if (ordersFilter === 'today') {
    const todayStart = new Date()
    todayStart.setHours(0, 0, 0, 0)
    return t >= todayStart.getTime()
  }
  if (ordersFilter === 'week') return t >= now - 7 * 86400000
  return t >= now - 30 * 86400000
})

if (loading) return <LoadingScreen />
if (notFound) return <FarmerNotFound onLogout={handleLogout} />

const profileComplete = isProfileComplete(farmer)
const displayName = farmer!.name?.trim() || tx.welcome

return (
  <main className="min-h-screen bg-gray-50 pb-16">
    {/* Header */}
    <div className="bg-green-900 px-4 pt-6 pb-10">
      <div className="flex justify-end mb-2">

const [liveQrUrls, setLiveQrUrls] = useState<Record<string, string>>({})
// Live COD acceptance per farmer (default false until fetched)
const [liveCodEnabled, setLiveCodEnabled] = useState<Record<string, boolean>>({})
const [showUpiAppFallback, setShowUpiAppFallback] = useState(false)
const [utrNote, setUtrNote] = useState('')
// Mandatory payment screenshot upload (UPI flow)
const [proofFile, setProofFile] = useState<File | null>(null)
const [proofPreview, setProofPreview] = useState('')
const [proofUploading, setProofUploading] = useState(false)
const [proofUploaded, setProofUploaded] = useState(false)
const [proofError, setProofError] = useState('')
const [cashMode, setCashMode] = useState(false)
const [switchingToCash, setSwitchingToCash] = useState(false)
const [upiScreen, setUpiScreen] = useState<UpiPaymentState | null>(null)

// Refs for use inside event listeners (avoids stale closures)
const upiScreenRef = useRef<UpiPaymentState | null>(null)
const autoTriggeredRef = useRef(false)

useEffect(() => { upiScreenRef.current = upiScreen }, [upiScreen])

// Update payment status to claimed and clear cart. The farmer is alerted via
// the realtime subscription on their dashboard — no WhatsApp message opened.
const triggerPostPayment = useCallback(async (screen: UpiPaymentState, utrRef: string) => {
  setSubmittingResult(true)
  const updateData: Record<string, unknown> = { payment_status: 'pending_confirmation' }
  if (utrRef.trim()) updateData.utr_number = utrRef.trim()
  await Promise.all(
    screen.orderIds.map((id) =>
      supabase.from('orders').update(updateData).eq('id', id)
    )
  )
  clearFarmer(screen.farmerId)
  localStorage.removeItem(UPI_PENDING_KEY)
  localStorage.removeItem(UPI_LAUNCHED_KEY)
  setSubmittingResult(false)
  setPaidDone(true)
}, [clearFarmer])

// Keep a ref to triggerPostPayment so visibilitychange handler is never stale
const triggerPostPaymentRef = useRef(triggerPostPayment)
useEffect(() => { triggerPostPaymentRef.current = triggerPostPayment }, [triggerPostPayment])

// On mount: only restore payment screen when UPI app was actually launched.
// If launched is missing the user just viewed (or closed) the payment screen — don't restore.
useEffect(() => {
  const pending = localStorage.getItem(UPI_PENDING_KEY)
  const launched = localStorage.getItem(UPI_LAUNCHED_KEY)
  if (!pending || !launched) return
  try {
    const saved = JSON.parse(pending) as UpiPaymentState
    setUpiScreen(saved)
    if (!autoTriggeredRef.current) {
      autoTriggeredRef.current = true
      triggerPostPayment(saved, '')
    }
  } catch { /* ignore corrupt data */ }
// eslint-disable-next-line react-hooks/exhaustive-deps
}, []) // intentionally runs once on mount only

// Persist upiScreen to localStorage whenever it changes
useEffect(() => {
  if (upiScreen) localStorage.setItem(UPI_PENDING_KEY, JSON.stringify(upiScreen))
}, [upiScreen])

// When user returns from UPI app (no page reload): auto-trigger WhatsApp
useEffect(() => {
  const handleVisibility = () => {
    if (document.visibilityState !== 'visible') return
    if (!localStorage.getItem(UPI_LAUNCHED_KEY)) return
    if (autoTriggeredRef.current) return
    const screen = upiScreenRef.current
    if (!screen) return
    autoTriggeredRef.current = true
    triggerPostPaymentRef.current(screen, '')
  }
  document.addEventListener('visibilitychange', handleVisibility)
  return () => document.removeEventListener('visibilitychange', handleVisibility)
}, [])

// Fetch latest UPI IDs and QR codes for all farmers in cart when sheet opens
useEffect(() => {
  const farmerIds = [...new Set(items.map((i) => i.farmerId).filter(Boolean))]
  if (farmerIds.length === 0) return
  supabase
    .from('farmers')
    .select('id, upi_id, upi_qr_code_url, cod_enabled')
    .in('id', farmerIds)
    .then(({ data }) => {
      if (!data) return
      const upiMap: Record<string, string> = {}
      const qrMap: Record<string, string> = {}
      const codMap: Record<string, boolean> = {}
      for (const f of data) {
        if (f.upi_id) upiMap[f.id] = f.upi_id
        if (f.upi_qr_code_url) qrMap[f.id] = f.upi_qr_code_url
        codMap[f.id] = f.cod_enabled === true
      }
      setLiveUpiIds(upiMap)
      setLiveQrUrls(qrMap)
      setLiveCodEnabled(codMap)
    })
}, [items])

useEffect(() => {
  setName(info.name)
  setPhone(info.phone)
}, [info])

// When the consumer logs in, prefer their authenticated profile over any

  if (!upiScreen) return
  setProofUploading(true)
  const fd = new FormData()
  fd.append('orderIds', upiScreen.orderIds.join(','))
  fd.append('file', compressed)
  const r = await fetch('/api/orders/upload-proof', {
    method: 'POST',
    body: fd,
    credentials: 'same-origin',
  }).catch(() => null)
  setProofUploading(false)
  if (!r) {
    setProofError('Upload failed — check your connection and try again.')
    return
  }
  const json = await r.json().catch(() => ({}))
  if (!r.ok || !json?.ok) {
    setProofError(json?.error ?? 'Upload failed.')
    return
  }
  setProofUploaded(true)
}

const handlePaymentSuccess = async () => {
  if (!upiScreen) return
  if (!proofUploaded) {
    setProofError('Please attach your payment screenshot first.')
    return
  }
  await triggerPostPayment(upiScreen, utrNote)
}

const handleCashOnPickup = async () => {
  if (!upiScreen) return
  setSwitchingToCash(true)
  await Promise.all(
    upiScreen.orderIds.map((id) =>
      supabase.from('orders').update({ payment_method: 'cod', payment_status: 'pending' }).eq('id', id)
    )
  )
  clearFarmer(upiScreen.farmerId)
  localStorage.removeItem(UPI_PENDING_KEY)
  localStorage.removeItem(UPI_LAUNCHED_KEY)
  setSwitchingToCash(false)
  setCashMode(true)
  setPaidDone(true)
}

const handleOpenUpiApp = () => {
  localStorage.setItem(UPI_LAUNCHED_KEY, '1')
  setShowUpiAppFallback(false)
  // target="_blank" keeps the current page alive when the OS hands off to the UPI app
  const a = document.createElement('a')
  a.href = 'upi://pay'
  a.target = '_blank'
  a.rel = 'noopener noreferrer'
  document.body.appendChild(a)
  a.click()
  document.body.removeChild(a)
  setTimeout(() => setShowUpiAppFallback(true), 2500)

